	"level" double precision /* f64 */
) RETURNS double precision[] /* alloc::vec::Vec<f64> */
IMMUTABLE STRICT PARALLEL SAFE
LANGUAGE c /* Rust */
AS 'MODULE_PATHNAME', 'morlet_simple_value_floors_wrapper';

